sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Create an instance of our TimeTrackerUtils Script Include so we can call its functions
    var utils = new x_783736_time_tr_0.TimeTrackerUtils();

    // Only look up Team and Hourly Rate if this is a brand-new Time Entry OR the Employee changed
    // This protects historical records so old entries don't change cost if someone gets promoted later!
    if (current.isNewRecord() || current.employee.changes()) {
        var empId = current.getValue('employee');

        // Get the employee's team array (e.g., ['sys_id_of_DPOS_Team']) and stamp the first team
        var teams = utils._getUserTimeTrackerTeams(empId);
        if (teams.length > 0) {
            current.setValue('team', teams[0]);
        }

        // Calculate the employee's hourly rate from their Classification Level & Schedule, and save a snapshot
        var hourlyRate = utils.getUserHourlyRate(empId);
        current.setValue('hourly_rate_snapshot', hourlyRate);
    }

    // Multiply hours worked by the stamped hourly rate to get total dollar cost for this entry
    var hours = parseFloat(current.getValue('hours')) || 0;
    var rate = parseFloat(current.getValue('hourly_rate_snapshot')) || 0;
    current.setValue('calculated_cost', hours * rate);

})(current, previous);
